-- ------------------------------------------------------------------ registrants
INSERT INTO registrations (id, event_id, user_id, dept, status, checked_in, checked_in_at, attend_via, food_allergy, dietary_pref, registered_at)
SELECT 105500 + ROW_NUMBER() OVER (ORDER BY u.id), 1055, u.id, u.dept,
       IF(u.id = 1005, 'absent', 'attended'),
       IF(u.id = 1005, 0, 1),
       IF(u.id = 1005, NULL, TIMESTAMP('2026-09-12', SEC_TO_TIME(8 * 3600 + 5 * 60 + (u.id % 25) * 60))),
       'onsite',
       CASE u.id WHEN 1003 THEN 'กุ้ง' WHEN 1015 THEN 'ถั่วลิสง' END,
       CASE u.id WHEN 1009 THEN 'ไม่ทานเนื้อวัว' END,
       TIMESTAMP('2026-08-24' + INTERVAL (u.id % 17) DAY, '19:50:00')
FROM users u
WHERE u.role = 'student'
  AND u.id % 2 = 1
  AND NOT EXISTS (SELECT 1 FROM blacklist_entries b WHERE b.user_id = u.id AND b.restored_at IS NULL);

INSERT INTO registration_checkins (registration_id, event_date, checked_in_at)
SELECT r.id, '2026-09-12', r.checked_in_at FROM registrations r WHERE r.event_id = 1055 AND r.checked_in = 1;

